function getIntEnv(
  name: string,
  fallback: number,
  minValue: number,
): number {
  const raw = process.env[name];
  if (raw == null || raw === "") return fallback;
  const value = Number.parseInt(String(raw), 10);
  if (!Number.isInteger(value) || value < minValue) {
    throw new Error(`Invalid integer for ${name}: ${raw}`);
  }
  return value;
}

function getBoolEnv(name: string, fallback: boolean): boolean {
  const raw = process.env[name];
  if (raw == null || raw === "") return fallback;
  const normalized = String(raw).trim().toLowerCase();
  if (["1", "true", "yes", "y", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "n", "off"].includes(normalized)) return false;
  throw new Error(`Invalid boolean for ${name}: ${raw}`);
}

function firstDefined<T>(...values: T[]): T | undefined {
  for (const value of values) {
    if (value !== undefined && value !== null) return value;
  }
  return undefined;
}

function firstNonEmpty(...values: Array<string | null | undefined>): string | null {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return null;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Object.prototype.toString.call(value) === "[object Object]";
}

function deepMerge<T>(base: T, override: unknown): T {
  if (!isPlainObject(base) || !isPlainObject(override)) return override as T;
  const merged: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (isPlainObject(value) && isPlainObject(merged[key])) {
      merged[key] = deepMerge(merged[key] as Record<string, unknown>, value);
    } else {
      merged[key] = value;
    }
  }
  return merged as T;
}

function parseJsonMaybe(text: string | null | undefined): unknown | null {
  if (typeof text !== "string") return null;
  const trimmed = text.trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(trimmed);
  } catch {
    return null;
  }
}

function readTrimmedFile(filePath: string): string | null {
  try {
    const content = fs.readFileSync(filePath, "utf8");
    const trimmed = content.trim();
    return trimmed || null;
  } catch {
    return null;
  }
}

function getToken(): string | null {
  return firstNonEmpty(
    process.env.TENSORMESH_CONTROL_PLANE_TOKEN,
    readTrimmedFile(TOKEN_FILE),
  );
}

function requireToken(): string {
  const token = getToken();
  if (!token) {
    throw new Error(
      "No Tensormesh Control Plane token found in TENSORMESH_CONTROL_PLANE_TOKEN or token file.",
    );
  }
  return token;
}

function buildHeaders(
  token: string,
  extraHeaders: Record<string, string> = {},
): Record<string, string> {
  return {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
    Accept: "application/json",
    ...extraHeaders,
  };
}

function buildUrl(pathname: string): string {
  return new URL(pathname.replace(/^\/+/, ""), `${CONTROL_PLANE_BASE}/`).toString();
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchWithTimeout(
  url: string,
  options: RequestInit,
  timeoutMs: number,
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      const timeoutError = new Error(`Request timed out after ${timeoutMs}ms`) as Error & {
        code?: string;
      };
      timeoutError.code = "ETIMEDOUT";
      throw timeoutError;
    }
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

function shouldRetry(error: unknown, responseStatus?: number | null): boolean {
  if (responseStatus != null) {
    return responseStatus >= 500 || responseStatus === 429;
  }
  if (!(error instanceof Error)) return false;
  if ((error as Error & { code?: string }).code === "ETIMEDOUT") return true;
  const message = error.message.toLowerCase();
  return (
    message.includes("network") ||
    message.includes("fetch failed") ||
    message.includes("socket") ||
    message.includes("timed out") ||
    message.includes("econnreset") ||
    message.includes("econnrefused") ||
    message.includes("enotfound")
  );
}

function extractErrorMessage(
  payload: unknown,
  rawText: string,
  response?: Response,
): string {
  if (isPlainObject(payload)) {
    const nestedError = isPlainObject(payload.error) ? payload.error : undefined;
    const nestedDetail = isPlainObject(payload.detail) ? payload.detail : undefined;
    const candidates = [
      typeof payload.message === "string" ? payload.message : undefined,
      typeof payload.error === "string" ? payload.error : undefined,
      typeof payload.detail === "string" ? payload.detail : undefined,
      typeof payload.reason === "string" ? payload.reason : undefined,
      typeof payload.error_description === "string"
        ? payload.error_description
        : undefined,
      nestedError && typeof nestedError.message === "string"
        ? nestedError.message
        : undefined,
      nestedDetail && typeof nestedDetail.message === "string"
        ? nestedDetail.message
        : undefined,
    ];
    for (const candidate of candidates) {
      if (typeof candidate === "string" && candidate.trim()) {
        return candidate.trim();
      }
    }
  }
  if (typeof rawText === "string" && rawText.trim()) return rawText.trim();
  if (response) return `${response.status} ${response.statusText}`.trim();
  return "Unknown error";
}

type RequestJsonResult = {
  response: Response;
  rawText: string;
  data: Record<string, unknown>;
};

async function requestJson(
  method: string,
  pathname: string,
  token: string,
  body?: unknown,
): Promise<RequestJsonResult> {
  const url = buildUrl(pathname);
  let lastError: unknown = null;
  for (let attempt = 0; attempt <= HTTP_RETRIES; attempt++) {
    try {
      const response = await fetchWithTimeout(
        url,
        {
          method,
          headers: buildHeaders(token),
          body: body === undefined ? undefined : JSON.stringify(body),
        },
        REQUEST_TIMEOUT_MS,
      );
      const rawText = await response.text();
      const payload = parseJsonMaybe(rawText);
      if (!response.ok) {
        const error = new Error(
          `HTTP ${response.status}: ${extractErrorMessage(payload, rawText, response)}`,
        ) as Error & {
          status?: number;
          statusText?: string;
          payload?: unknown;
          rawText?: string;
        };
        error.status = response.status;
        error.statusText = response.statusText;
        error.payload = payload;
        error.rawText = rawText;
        if (attempt < HTTP_RETRIES && shouldRetry(null, response.status)) {
          lastError = error;
          await sleep(Math.min(1000 * 2 ** attempt, 8000));
          continue;
        }
        throw error;
      }
      return {
        response,
        rawText,
        data:
          payload && isPlainObject(payload)
            ? (payload as Record<string, unknown>)
            : { raw: rawText },
      };
    } catch (error) {
      lastError = error;
      if (attempt < HTTP_RETRIES && shouldRetry(error, null)) {
        await sleep(Math.min(1000 * 2 ** attempt, 8000));
        continue;
      }
      throw error;
    }
  }
  throw lastError || new Error(`Request failed: ${method} ${url}`);
}

type NormalizedEvent = {
  createdAt: string;
  eventType: string;
  log: string;
};

function normalizeEvent(event: unknown): NormalizedEvent {
  if (!isPlainObject(event)) {
    return {
      createdAt: "-",
      eventType: "UNKNOWN",
      log: String(event),
    };
  }
  return {
    createdAt: String(
      firstDefined(
        event.createdAt,
        event.created_at,
        event.timestamp,
        "-",
      ),
    ),
    eventType: String(
      firstDefined(
        event.eventType,
        event.event_type,
        event.type,
        "UNKNOWN",
      ),
    ),
    log: String(firstDefined(event.log, event.message, event.details, "")),
  };
}

type NormalizedModel = {
  raw: Record<string, unknown>;
  modelId?: string;
  modelName?: string;
  modelPath?: string;
  endpoint?: string;
  apiKey?: string;
  status: string;
  gpuType: unknown;
  gpuCount: unknown;
  infra: Record<string, unknown> | null;
  events: NormalizedEvent[];
};

function normalizeModel(input: unknown): NormalizedModel {
  const model = isPlainObject(input) ? input : {};
  const rawEvents = Array.isArray(model.events)
    ? model.events
    : Array.isArray(model.history)
      ? model.history
      : Array.isArray(model.logs)
        ? model.logs
        : [];
  return {
    raw: model,
    modelId: firstDefined(
      typeof model.modelId === "string" ? model.modelId : undefined,
      typeof model.model_id === "string" ? model.model_id : undefined,
      typeof model.id === "string" ? model.id : undefined,
    ),
    modelName: firstDefined(
      typeof model.modelName === "string" ? model.modelName : undefined,
      typeof model.model_name === "string" ? model.model_name : undefined,
      typeof model.name === "string" ? model.name : undefined,
    ),
    modelPath: firstDefined(
      typeof model.modelPath === "string" ? model.modelPath : undefined,
      typeof model.model_path === "string" ? model.model_path : undefined,
      typeof model.path === "string" ? model.path : undefined,
    ),
    endpoint: firstDefined(
      typeof model.endpoint === "string" ? model.endpoint : undefined,
      typeof model.apiEndpoint === "string" ? model.apiEndpoint : undefined,
      typeof model.api_endpoint === "string" ? model.api_endpoint : undefined,
      typeof model.url === "string" ? model.url : undefined,
    ),
    apiKey: firstDefined(
      typeof model.apiKey === "string" ? model.apiKey : undefined,
      typeof model.api_key === "string" ? model.api_key : undefined,
    ),
    status: String(
      firstDefined(
        model.status,
        model.state,
        model.phase,
        model.deploymentStatus,
        "unknown",
      ),
    ),
    gpuType: firstDefined(model.gpuType, model.gpu_type, "-"),
    gpuCount: firstDefined(model.gpuCount, model.gpu_count, "-"),
    infra: isPlainObject(model.infra) ? model.infra : null,
    events: rawEvents.map(normalizeEvent),
  };
}

function sanitizeSingleLine(value: unknown): string {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

function isReadyStatus(status: string): boolean {
  const normalized = String(status).trim().toUpperCase();
  return (
    normalized === "MODEL_STATUS_RUNNING" ||
    normalized === "RUNNING" ||
    normalized === "READY" ||
    normalized === "ACTIVE"
  );
}

function isFailedStatus(status: string): boolean {
  const normalized = String(status).trim().toUpperCase();
  return (
    normalized === "MODEL_STATUS_FAILED" ||
    normalized === "MODEL_STATUS_ERROR" ||
    normalized === "FAILED" ||
    normalized === "ERROR" ||
    normalized === "CRASHED"
  );
}

function formatEventLines(events: NormalizedEvent[]): string {
  if (!Array.isArray(events) || events.length === 0) {
    return "No events available.";
  }
  return events
    .map(
      (event) =>
        `  [${event.createdAt}] ${event.eventType}: ${sanitizeSingleLine(event.log)}`,
    )
    .join("\n");
}

function detectTrustRemoteCodeFailure(events: NormalizedEvent[]): boolean {
  const haystack = Array.isArray(events)
    ? events
        .map((event) => `${event.eventType} ${event.log}`)
        .join("\n")
        .toLowerCase()
    : "";
  return (
    haystack.includes("trust_remote_code") ||
    (haystack.includes("custom code") && haystack.includes("hf.co"))
  );
}

function isConflictError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  const status = (error as Error & { status?: number }).status;
  if (status === 409) return true;
  const message = error.message.toLowerCase();
  return (
    message.includes("already exists") ||
    message.includes("already deployed") ||
    message.includes("already has") ||
    message.includes("duplicate") ||
    message.includes("conflict") ||
    message.includes("model name") ||
    message.includes("same name")
  );
}

function parseExtraDeployBody(): Record<string, unknown> {
  if (!EXTRA_DEPLOY_BODY_JSON.trim()) return {};
  const parsed = parseJsonMaybe(EXTRA_DEPLOY_BODY_JSON);
  if (!isPlainObject(parsed)) {
    throw new Error(
      "TENSORMESH_EXTRA_DEPLOY_BODY_JSON must be a valid JSON object.",
    );
  }
  return parsed;
}

function randomSuffix(length: number): string {
  return crypto.randomBytes(Math.ceil(length / 2)).toString("hex").slice(0, length);
}

function buildDeploymentName(): string {
  const explicitName = firstNonEmpty(process.env.TENSORMESH_DEPLOYMENT_NAME);
  if (explicitName) return explicitName;
  return `minimax-m27-${Date.now()}-${randomSuffix(8)}`;
}

function buildDeploymentBody(modelName: string): Record<string, unknown> {
  const vllmCliArgs = [
    "--trust-remote-code",
    "--tensor-parallel-size",
    String(GPU_COUNT),
    "--tool-call-parser",
    "minimax_m2",
    "--reasoning-parser",
    "minimax_m2",
    "--enable-auto-tool-choice",
  ];
  let body: Record<string, unknown> = {
    model_name: modelName,
    model_path: HF_MODEL_ID,
    gpu_count: GPU_COUNT,
    gpu_type: GPU_TYPE,
    trust_remote_code: true,
    args: vllmCliArgs,
    extra_args: vllmCliArgs,
    vllm_args: vllmCliArgs,
    serving_args: vllmCliArgs,
    cli_args: vllmCliArgs,
    engine_args: {
      trust_remote_code: true,
      tensor_parallel_size: GPU_COUNT,
      tool_call_parser: "minimax_m2",
      reasoning_parser: "minimax_m2",
      enable_auto_tool_choice: true,
    },
    vllm_engine_args: {
      trust_remote_code: true,
      tensor_parallel_size: GPU_COUNT,
      tool_call_parser: "minimax_m2",
      reasoning_parser: "minimax_m2",
      enable_auto_tool_choice: true,
    },
    model_config: {
      trust_remote_code: true,
    },
    env: {
      HF_TRUST_REMOTE_CODE: "1",
      VLLM_TRUST_REMOTE_CODE: "1",
      TRUST_REMOTE_CODE: "true",
      VLLM_WORKER_MULTIPROC_METHOD: "spawn",
    },
    infra: {
      cloud_provider: CLOUD_PROVIDER,
      ...(CLOUD_PROVIDER === "CLOUD_PROVIDER_NEBIUS" && NEBIUS_REGION
        ? { nebius_region: NEBIUS_REGION }
        : {}),
    },
    autoscaling_config: {
      enabled: AUTOSCALING_ENABLED,
      min_replicas: MIN_REPLICAS,
      max_replicas: MAX_REPLICAS,
      scale_down_policy: {
        scale_to_zero_delay_seconds: SCALE_TO_ZERO_DELAY_SECONDS,
        stabilization_window_seconds: SCALE_DOWN_STABILIZATION_SECONDS,
      },
      scale_up_policy: {
        stabilization_window_seconds: SCALE_UP_STABILIZATION_SECONDS,
      },
    },
  };
  if (HUGGINGFACE_TOKEN) {
    body = deepMerge(body, {
      env: {
        HF_TOKEN: HUGGINGFACE_TOKEN,
        HUGGING_FACE_HUB_TOKEN: HUGGINGFACE_TOKEN,
        HUGGINGFACE_TOKEN: HUGGINGFACE_TOKEN,
      },
    });
  }
  const extraBody = parseExtraDeployBody();
  if (Object.keys(extraBody).length > 0) {
    body = deepMerge(body, extraBody);
  }
  return body;
}

async function getModel(modelId: string, token: string): Promise<NormalizedModel> {
  const { data } = await requestJson(
    "GET",
    `/v1/models/${encodeURIComponent(modelId)}`,
    token,
  );
  return normalizeModel(
    isPlainObject(data.model) ? data.model : data,
  );
}

async function pollStatus(modelId: string, token: string): Promise<NormalizedModel> {
  for (let attempt = 0; attempt < MAX_POLLS; attempt++) {
    const model = await getModel(modelId, token);
    const elapsedSeconds = Math.floor((attempt * POLL_INTERVAL_MS) / 1000);
    const lastEvent =
      model.events.length > 0 ? model.events[model.events.length - 1] : null;
    console.log(
      `[POLL ${attempt + 1}/${MAX_POLLS}] status=${model.status} gpu=${model.gpuCount}x${model.gpuType} elapsed=${elapsedSeconds}s`,
    );
    if (lastEvent && lastEvent.log) {
      console.log(`  Last event: ${sanitizeSingleLine(lastEvent.log)}`);
    }
    if (isReadyStatus(model.status)) {
      console.log("");
      console.log("[READY] Model is live.");
      console.log(`  Model ID  : ${model.modelId || modelId}`);
      console.log(`  Model name: ${model.modelName || "-"}`);
      console.log(`  HF path   : ${model.modelPath || "-"}`);
      console.log(`  Endpoint  : ${model.endpoint || "-"}`);
      console.log(`  GPU       : ${model.gpuCount}x ${model.gpuType}`);
      if (model.infra) {
        console.log(`  Infra     : ${JSON.stringify(model.infra)}`);
      }
      return model;
    }
    if (isFailedStatus(model.status)) {
      const lines = formatEventLines(model.events);
      let message = `[FAILED] Deployment failed. Status: ${model.status}\n${lines}`;
      if (detectTrustRemoteCodeFailure(model.events)) {
        message +=
          `\n[HINT] The vLLM process did not receive --trust-remote-code.` +
          ` Set TENSORMESH_EXTRA_DEPLOY_BODY_JSON to override platform-specific arg mapping.` +
          ` Example: '{"args":["--trust-remote-code","--tensor-parallel-size","${GPU_COUNT}","--tool-call-parser","minimax_m2","--reasoning-parser","minimax_m2","--enable-auto-tool-choice"]}'`;
      }
      throw new Error(message);
    }
    if (attempt < MAX_POLLS - 1) {
      await sleep(POLL_INTERVAL_MS);
    }
  }
  throw new Error(
    `[TIMEOUT] Polling stopped after ${Math.floor((MAX_POLLS * POLL_INTERVAL_MS) / 1000)}s for model ${modelId}.`,
  );
}

async function createDeploymentWithRetries(
  token: string,
): Promise<{ data: Record<string, unknown>; modelName: string }> {
  let lastError: unknown = null;
  for (let attempt = 0; attempt < 10; attempt++) {
    const modelName = buildDeploymentName();
    const body = buildDeploymentBody(modelName);
    console.log(`[INFO] Deploying ${HF_MODEL_ID} to Tensormesh...`);
    console.log(`[INFO] model_name=${modelName}`);
    console.log(
      `[INFO] Deployment body args fields: args=${JSON.stringify(body.args)} extra_args=${JSON.stringify(body.extra_args)} vllm_args=${JSON.stringify(body.vllm_args)}`,
    );
    try {
      const { data } = await requestJson("POST", "/v1/models", token, body);
      return { data, modelName };
    } catch (error) {
      lastError = error;
      if (isConflictError(error) && !process.env.TENSORMESH_DEPLOYMENT_NAME) {
        console.error(
          `[WARN] Deployment name collision for ${modelName}. Retrying with a new unique name...`,
        );
        await sleep(500);
        continue;
      }
      throw error;
    }
  }
  throw lastError || new Error("Unable to create deployment after retries.");
}

async function deploy(): Promise<void> {
  const token = requireToken();
  const { data, modelName } = await createDeploymentWithRetries(token);
  const model = normalizeModel(isPlainObject(data.model) ? data.model : data);
  const modelId = model.modelId;
  if (!modelId) {
    const responseDump = JSON.stringify(data, null, 2);
    throw new Error(
      `Deployment response did not include a model ID for model_name=${modelName}.\n${responseDump}`,
    );
  }
  console.log(`[SUCCESS] Deployment created. modelId=${modelId}`);
  console.log("[INFO] Polling status...");
  await pollStatus(modelId, token);
}

async function checkActive(modelId: string): Promise<void> {
  const token = requireToken();
  console.log(`[INFO] Checking deployment: ${modelId}`);
  await pollStatus(modelId, token);
}

function logFatal(error: unknown): void {
  if (!error) {
    console.error("[FATAL] Unknown error");
    return;
  }
  if (error instanceof Error) {
    const message = error.message.trim() ? error.message : String(error);
    console.error(`[FATAL] ${message}`);
    const enriched = error as Error & {
      status?: number;
      statusText?: string;
      payload?: unknown;
      rawText?: string;
    };
    if (enriched.status) {
      console.error(
        `HTTP Status: ${enriched.status}${enriched.statusText ? ` ${enriched.statusText}` : ""}`,
      );
    }
    if (enriched.payload) {
      try {
        console.error(JSON.stringify(enriched.payload, null, 2));
        return;
      } catch {}
    }
    if (typeof enriched.rawText === "string" && enriched.rawText.trim()) {
      console.error(enriched.rawText);
    }
    return;
  }
  console.error(`[FATAL] ${String(error)}`);
}

async function main(): Promise<void> {
  const mode = String(process.argv[2] || "deploy")
    .trim()
    .toLowerCase();
  if (mode === "status") {
    const modelId = firstNonEmpty(process.argv[3], ACTIVE_MODEL_ID);
    if (!modelId) {
      throw new Error(
        'No model ID provided. Pass it as argv[3] or set TENSORMESH_ACTIVE_MODEL_ID.',
      );
    }
    await checkActive(modelId);
    return;
  }
  if (mode === "deploy") {
    await deploy();
    return;
  }
  throw new Error(`Unknown mode: ${mode}. Use "deploy" or "status".`);
}

main().catch((error) => {
  logFatal(error);
  process.exit(1);
});
