MIN_REPLICAS = _get_int_env("TENSORMESH_MIN_REPLICAS", 0, 0)
MAX_REPLICAS = _get_int_env("TENSORMESH_MAX_REPLICAS", 4, 0)
SCALE_TO_ZERO_DELAY_SECONDS = _get_int_env("TENSORMESH_SCALE_TO_ZERO_DELAY_SECONDS", 300, 0)
SCALE_DOWN_STABILIZATION_SECONDS = _get_int_env("TENSORMESH_SCALE_DOWN_STABILIZATION_SECONDS", 60, 0)
SCALE_UP_STABILIZATION_SECONDS = _get_int_env("TENSORMESH_SCALE_UP_STABILIZATION_SECONDS", 30, 0)

HUGGINGFACE_TOKEN = next(
    (
        v.strip()
        for v in (
            os.environ.get("TENSORMESH_HUGGINGFACE_TOKEN"),
            os.environ.get("HUGGINGFACE_TOKEN"),
            os.environ.get("HF_TOKEN"),
            os.environ.get("HUGGING_FACE_HUB_TOKEN"),
        )
        if isinstance(v, str) and v.strip()
    ),
    None,
)

ACTIVE_MODEL_ID = next(
    (
        v.strip()
        for v in (os.environ.get("TENSORMESH_ACTIVE_MODEL_ID"),)
        if isinstance(v, str) and v.strip()
    ),
    None,
)


def _first_non_empty(*values):
    for v in values:
        if isinstance(v, str) and v.strip():
            return v.strip()
    return None


def _is_plain_dict(value):
    return isinstance(value, dict)


def _deep_merge(base, override):
    if not _is_plain_dict(base) or not _is_plain_dict(override):
        return override
    merged = dict(base)
    for key, value in override.items():
        if _is_plain_dict(value) and _is_plain_dict(merged.get(key)):
            merged[key] = _deep_merge(merged[key], value)
        else:
            merged[key] = value
    return merged


def _parse_json_maybe(text):
    if not isinstance(text, (str, bytes)):
        return None
    try:
        trimmed = text.strip() if isinstance(text, str) else text.decode("utf-8").strip()
        if not trimmed:
            return None
        return json.loads(trimmed)
    except (ValueError, UnicodeDecodeError):
        return None


def _read_trimmed_file(file_path):
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read().strip()
        return content if content else None
    except OSError:
        return None


def _get_token():
    return _first_non_empty(
        os.environ.get("TENSORMESH_CONTROL_PLANE_TOKEN"),
        _read_trimmed_file(TOKEN_FILE),
    )


def _require_token():
    token = _get_token()
    if not token:
        raise RuntimeError(
            "No Tensormesh Control Plane token found in TENSORMESH_CONTROL_PLANE_TOKEN or token file."
        )
    return token


def _build_url(pathname):
    base = CONTROL_PLANE_BASE.rstrip("/")
    path = pathname.lstrip("/")
    return f"{base}/{path}"


def _should_retry(exc, status_code=None):
    if status_code is not None:
        return status_code >= 500 or status_code == 429
    if exc is None:
        return False
    msg = str(exc).lower()
    return any(
        token in msg
        for token in ("timeout", "timed out", "network", "socket", "connection reset", "connection refused", "name or service not known")
    )


def _extract_error_message(payload, raw_text, status_code=None, reason=None):
    if _is_plain_dict(payload):
        for key in ("message", "error", "detail", "reason", "error_description"):
            candidate = payload.get(key)
            if isinstance(candidate, str) and candidate.strip():
                return candidate.strip()
            if _is_plain_dict(candidate):
                nested = candidate.get("message")
                if isinstance(nested, str) and nested.strip():
                    return nested.strip()
    if isinstance(raw_text, (str, bytes)):
        text = raw_text.decode("utf-8", errors="replace") if isinstance(raw_text, bytes) else raw_text
        if text.strip():
            return text.strip()
    if status_code and reason:
        return f"{status_code} {reason}"
    return "Unknown error"


def _request_json(method, pathname, token, body=None):
    url = _build_url(pathname)
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    encoded_body = json.dumps(body).encode("utf-8") if body is not None else None
    last_exc = None
    for attempt in range(HTTP_RETRIES + 1):
        try:
            req = urllib.request.Request(url, data=encoded_body, headers=headers, method=method)
            with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT_S) as resp:
                raw = resp.read()
                payload = _parse_json_maybe(raw)
                return {
                    "status": resp.status,
                    "raw": raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else raw,
                    "data": payload if _is_plain_dict(payload) else {"raw": raw},
                }
        except urllib.error.HTTPError as exc:
            raw = b""
            try:
                raw = exc.read()
            except Exception:
                pass
            payload = _parse_json_maybe(raw)
            raw_text = raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else str(raw)
            error_msg = _extract_error_message(payload, raw_text, exc.code, exc.reason)
            http_exc = RuntimeError(f"HTTP {exc.code}: {error_msg}")
            http_exc.status_code = exc.code
            http_exc.payload = payload
            http_exc.raw_text = raw_text
            last_exc = http_exc
            if attempt < HTTP_RETRIES and _should_retry(None, exc.code):
                time.sleep(min(1.0 * (2 ** attempt), 8.0))
                continue
            raise http_exc
        except Exception as exc:
            last_exc = exc
            if attempt < HTTP_RETRIES and _should_retry(exc):
                time.sleep(min(1.0 * (2 ** attempt), 8.0))
                continue
            raise
    raise last_exc or RuntimeError(f"Request failed: {method} {url}")


def _normalize_event(event):
    if not _is_plain_dict(event):
        return {"createdAt": "-", "eventType": "UNKNOWN", "log": str(event)}
    return {
        "createdAt": str(event.get("createdAt") or event.get("created_at") or event.get("timestamp") or "-"),
        "eventType": str(event.get("eventType") or event.get("event_type") or event.get("type") or "UNKNOWN"),
        "log": str(event.get("log") or event.get("message") or event.get("details") or ""),
    }


def _normalize_model(data):
    model = data if _is_plain_dict(data) else {}
    raw_events = model.get("events") or model.get("history") or model.get("logs") or []
    if not isinstance(raw_events, list):
        raw_events = []
    return {
        "raw": model,
        "modelId": model.get("modelId") or model.get("model_id") or model.get("id"),
        "modelName": model.get("modelName") or model.get("model_name") or model.get("name"),
        "modelPath": model.get("modelPath") or model.get("model_path") or model.get("path"),
        "endpoint": model.get("endpoint") or model.get("apiEndpoint") or model.get("api_endpoint") or model.get("url"),
        "apiKey": model.get("apiKey") or model.get("api_key"),
        "status": str(model.get("status") or model.get("state") or model.get("phase") or model.get("deploymentStatus") or "unknown"),
        "gpuType": model.get("gpuType") or model.get("gpu_type") or "-",
        "gpuCount": model.get("gpuCount") or model.get("gpu_count") or "-",
        "infra": model.get("infra") if _is_plain_dict(model.get("infra")) else None,
        "events": [_normalize_event(e) for e in raw_events],
    }


def _sanitize_single_line(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _is_ready_status(status):
    normalized = str(status).strip().upper()
    return normalized in ("MODEL_STATUS_RUNNING", "RUNNING", "READY", "ACTIVE")


def _is_failed_status(status):
    normalized = str(status).strip().upper()
    return normalized in ("MODEL_STATUS_FAILED", "MODEL_STATUS_ERROR", "FAILED", "ERROR", "CRASHED")


def _format_event_lines(events):
    if not events:
        return "No events available."
    return "\n".join(
        f"  [{e['createdAt']}] {e['eventType']}: {_sanitize_single_line(e['log'])}"
        for e in events
    )


def _detect_trust_remote_code_failure(events):
    haystack = "\n".join(f"{e['eventType']} {e['log']}" for e in events).lower()
    return "trust_remote_code" in haystack or (
        "custom code" in haystack and "hf.co" in haystack
    )


def _is_conflict_error(exc):
    status = getattr(exc, "status_code", None)
    if status == 409:
        return True
    msg = str(exc).lower()
    return any(
        token in msg
        for token in (
            "already exists",
            "already deployed",
            "already has",
            "duplicate",
            "conflict",
            "model name",
            "same name",
            "unique",
        )
    )


def _parse_extra_deploy_body():
    if not EXTRA_DEPLOY_BODY_JSON.strip():
        return {}
    parsed = _parse_json_maybe(EXTRA_DEPLOY_BODY_JSON)
    if not _is_plain_dict(parsed):
        raise ValueError("TENSORMESH_EXTRA_DEPLOY_BODY_JSON must be a valid JSON object.")
    return parsed


def _random_suffix(length=8):
    return secrets.token_hex(max(1, length // 2))[:length]


def _build_deployment_name():
    explicit = _first_non_empty(os.environ.get("TENSORMESH_DEPLOYMENT_NAME"))
    if explicit:
        return explicit
    return f"minimax-m27-{int(time.time())}-{_random_suffix(8)}"


def _build_vllm_args():
    return [
        "--trust-remote-code",
        "--tensor-parallel-size",
        str(GPU_COUNT),
        "--tool-call-parser",
        "minimax_m2",
        "--reasoning-parser",
        "minimax_m2",
        "--enable-auto-tool-choice",
        "--compilation-config",
        json.dumps({"mode": 3, "pass_config": {"fuse_minimax_qk_norm": True}}),
    ]


def _build_deployment_body(model_name):
    vllm_cli_args = _build_vllm_args()
    infra_block = {"cloudProvider": CLOUD_PROVIDER}
    if CLOUD_PROVIDER == "CLOUD_PROVIDER_NEBIUS" and NEBIUS_REGION:
        infra_block["nebiusRegion"] = NEBIUS_REGION

    model_spec = {
        "trust_remote_code": True,
        "args": vllm_cli_args,
        "extra_args": vllm_cli_args,
        "vllm_args": vllm_cli_args,
        "serving_args": vllm_cli_args,
        "cli_args": vllm_cli_args,
        "engine_args": {
            "trust_remote_code": True,
            "tensor_parallel_size": GPU_COUNT,
            "tool_call_parser": "minimax_m2",
            "reasoning_parser": "minimax_m2",
            "enable_auto_tool_choice": True,
        },
        "vllm_engine_args": {
            "trust_remote_code": True,
            "tensor_parallel_size": GPU_COUNT,
            "tool_call_parser": "minimax_m2",
            "reasoning_parser": "minimax_m2",
            "enable_auto_tool_choice": True,
        },
        "env": {
            "HF_TRUST_REMOTE_CODE": "1",
            "VLLM_TRUST_REMOTE_CODE": "1",
            "TRUST_REMOTE_CODE": "true",
            "VLLM_WORKER_MULTIPROC_METHOD": "spawn",
        },
        "autoscaling_config": {
            "enabled": AUTOSCALING_ENABLED,
            "min_replicas": MIN_REPLICAS,
            "max_replicas": MAX_REPLICAS,
            "scale_down_policy": {
                "scale_to_zero_delay_seconds": SCALE_TO_ZERO_DELAY_SECONDS,
                "stabilization_window_seconds": SCALE_DOWN_STABILIZATION_SECONDS,
            },
            "scale_up_policy": {
                "stabilization_window_seconds": SCALE_UP_STABILIZATION_SECONDS,
            },
        },
    }

    body = {
        "modelName": model_name,
        "modelPath": HF_MODEL_ID,
        "gpuCount": GPU_COUNT,
        "gpuType": GPU_TYPE,
        "infra": infra_block,
        "kvCacheEnabled": True,
        "modelSpec": model_spec,
    }

    if HUGGINGFACE_TOKEN:
        body["hfToken"] = HUGGINGFACE_TOKEN
        model_spec["env"]["HF_TOKEN"] = HUGGINGFACE_TOKEN
        model_spec["env"]["HUGGING_FACE_HUB_TOKEN"] = HUGGINGFACE_TOKEN
        model_spec["env"]["HUGGINGFACE_TOKEN"] = HUGGINGFACE_TOKEN

    extra_body = _parse_extra_deploy_body()
    if extra_body:
        body = _deep_merge(body, extra_body)

    return body


def _get_model(model_id, token):
    result = _request_json("GET", f"/v1/models/{urllib.parse.quote(model_id, safe='')}", token)
    data = result["data"]
    return _normalize_model(data.get("model") if _is_plain_dict(data.get("model")) else data)


def _poll_status(model_id, token):
    for attempt in range(MAX_POLLS):
        model = _get_model(model_id, token)
        elapsed_s = attempt * POLL_INTERVAL_S
        last_event = model["events"][-1] if model["events"] else None
        print(
            f"[POLL {attempt + 1}/{MAX_POLLS}] status={model['status']} "
            f"gpu={model['gpuCount']}x{model['gpuType']} elapsed={elapsed_s}s"
        )
        if last_event and last_event["log"]:
            print(f"  Last event: {_sanitize_single_line(last_event['log'])}")

        if _is_ready_status(model["status"]):
            print("")
            print("[READY] Model is live.")
            print(f"  Model ID  : {model['modelId'] or model_id}")
            print(f"  Model name: {model['modelName'] or '-'}")
            print(f"  HF path   : {model['modelPath'] or '-'}")
            print(f"  Endpoint  : {model['endpoint'] or '-'}")
            print(f"  API Key   : {model['apiKey'] or '-'}")
            print(f"  GPU       : {model['gpuCount']}x {model['gpuType']}")
            if model["infra"]:
                print(f"  Infra     : {json.dumps(model['infra'])}")
            return model

        if _is_failed_status(model["status"]):
            lines = _format_event_lines(model["events"])
            message = f"[FAILED] Deployment failed. Status: {model['status']}\n{lines}"
            if _detect_trust_remote_code_failure(model["events"]):
                message += (
                    f"\n[HINT] The vLLM process did not receive --trust-remote-code."
                    f" Set TENSORMESH_EXTRA_DEPLOY_BODY_JSON to override platform-specific arg mapping."
                    f' Example: \'{{"modelSpec":{{"args":["--trust-remote-code","--tensor-parallel-size","{GPU_COUNT}","--tool-call-parser","minimax_m2","--reasoning-parser","minimax_m2","--enable-auto-tool-choice"]}}}}\''
                )
            raise RuntimeError(message)

        if attempt < MAX_POLLS - 1:
            time.sleep(POLL_INTERVAL_S)

    raise RuntimeError(
        f"[TIMEOUT] Polling stopped after {MAX_POLLS * POLL_INTERVAL_S}s for model {model_id}."
    )


def _create_deployment_with_retries(token):
    last_exc = None
    explicit_name = _first_non_empty(os.environ.get("TENSORMESH_DEPLOYMENT_NAME"))
    for attempt in range(10):
        model_name = explicit_name if explicit_name else _build_deployment_name()
        body = _build_deployment_body(model_name)
        print(f"[INFO] Deploying {HF_MODEL_ID} to Tensormesh...")
        print(f"[INFO] model_name={model_name}")
        vllm_args = body.get("modelSpec", {}).get("args", [])
        print(f"[INFO] vllm args: {json.dumps(vllm_args)}")
        try:
            result = _request_json("POST", "/v1/models", token, body)
            return result["data"], model_name
        except Exception as exc:
            last_exc = exc
            if _is_conflict_error(exc) and not explicit_name:
                print(
                    f"[WARN] Deployment name collision for {model_name}. Retrying with a new unique name..."
                )
                time.sleep(0.5)
                continue
            raise
    raise last_exc or RuntimeError("Unable to create deployment after retries.")


def _deploy():
    token = _require_token()
    data, model_name = _create_deployment_with_retries(token)
    model = _normalize_model(data.get("model") if _is_plain_dict(data.get("model")) else data)
    model_id = model["modelId"]
    if not model_id:
        response_dump = json.dumps(data, indent=2)
        raise RuntimeError(
            f"Deployment response did not include a model ID for model_name={model_name}.\n{response_dump}"
        )
    print(f"[SUCCESS] Deployment created. modelId={model_id}")
    print("[INFO] Polling status...")
    _poll_status(model_id, token)


def _check_active(model_id):
    token = _require_token()
    print(f"[INFO] Checking deployment: {model_id}")
    _poll_status(model_id, token)


def _log_fatal(exc):
    if exc is None:
        print("[FATAL] Unknown error", file=sys.stderr)
        return
    message = str(exc).strip() if str(exc).strip() else repr(exc)
    print(f"[FATAL] {message}", file=sys.stderr)
    status_code = getattr(exc, "status_code", None)
    if status_code:
        print(f"HTTP Status: {status_code}", file=sys.stderr)
    payload = getattr(exc, "payload", None)
    if payload:
        try:
            print(json.dumps(payload, indent=2), file=sys.stderr)
            return
        except Exception:
            pass
    raw_text = getattr(exc, "raw_text", None)
    if isinstance(raw_text, str) and raw_text.strip():
        print(raw_text, file=sys.stderr)


import urllib.parse


def main():
    mode = (sys.argv[1].strip().lower() if len(sys.argv) > 1 else "deploy")

    if mode == "status":
        model_id = _first_non_empty(
            sys.argv[2] if len(sys.argv) > 2 else None,
            ACTIVE_MODEL_ID,
        )
        if not model_id:
            raise RuntimeError(
                "No model ID provided. Pass it as argv[2] or set TENSORMESH_ACTIVE_MODEL_ID."
            )
        _check_active(model_id)
        return

    if mode == "deploy":
        _deploy()
        return

    raise RuntimeError(f'Unknown mode: {mode}. Use "deploy" or "status".')


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        _log_fatal(exc)
        sys.exit(1)
```

A legfontosabb változások a docs alapján:[2][1]

A Tensormesh API valódi mezőnevei camelCase-ek: `modelName`, `modelPath`, `gpuCount`, `gpuType`, `hfToken`, `infra.cloudProvider`, `infra.nebiusRegion`, `modelSpec` — ezek az előző JS verzióban snake_case-ként voltak beírva, ami valószínűleg oka volt a hibáknak is.  A MiniMax-M2.7 vLLM szerver indításához a `--compilation-config '{"mode":3,"pass_config":{"fuse_minimax_qk_norm":true}}'` flag is szükséges a docs szerint.  Az `ACTIVE_MODEL_ID` nincs alapértelmezve, deployment name ütközés esetén automatikusan új egyedi nevet generál.[1][2]
